{
  "title": "Facebook Profile Scraper",
  "description": "Paste public Facebook profile or Page links, usernames or numeric IDs. No login or cookies needed.",
  "type": "object",
  "schemaVersion": 1,
  "properties": {
    "startUrls": {
      "title": "Facebook profiles or Pages",
      "type": "array",
      "description": "One per line: a profile or Page URL (https://www.facebook.com/zuck), a numeric-id link (https://www.facebook.com/profile.php?id=4), a /people/<name>/<id>/ permalink, or just a username (zuck) or numeric ID (4). m.facebook.com, web.facebook.com and fb.com links work too. Duplicates are fetched once. Group, event, post, video and search links are not profiles and are skipped.",
      "editor": "stringList",
      "prefill": [
        "https://www.facebook.com/zuck",
        "https://www.facebook.com/BillGates"
      ]
    },
    "maxItems": {
      "title": "Max profiles",
      "type": "integer",
      "description": "Stop after this many profile rows. Default 1000; use a small number such as 10 for a test. Profiles that could not be delivered are never billed.",
      "minimum": 1,
      "default": 1000
    },
    "maxConcurrency": {
      "title": "Max parallel requests",
      "type": "integer",
      "description": "How many profiles are fetched at the same time, from 1 to 10. Default 4.",
      "minimum": 1,
      "maximum": 10,
      "default": 4
    },
    "proxy": {
      "title": "Proxy configuration",
      "type": "object",
      "description": "Optional. Leave empty to use the built-in residential pool. Facebook shows a login page to datacenter IPs, so if you set your own proxy, use a residential one, for example {\"useApifyProxy\": true, \"apifyProxyGroups\": [\"RESIDENTIAL\"]}.",
      "editor": "proxy"
    }
  },
  "required": [
    "startUrls"
  ]
}
